def drive(me, enemy, arena):
    # If we are holding the enemy, stay still
    if me.held:
        return (0.0, 0.0)

    # Compute bearing to enemy (degrees, left positive)
    bearing = bearing_to(enemy.x, enemy.y)

    # Simple proportional steering
    turn = max(min(bearing / 30.0, 1.0), -1.0)  # -1..1

    # Base forward throttle
    base = 0.8
    left = base * (1.0 - turn)
    right = base * (1.0 + turn)

    # Clamp to allowed range
    left = max(min(left, 1.0), -1.0)
    right = max(min(right, 1.0), -1.0)
    return (left, right)


def weapons(me, enemy, arena):
    cmds = []

    # Attempt to grab when within reach and not already holding
    if not me.held:
        if distance_to(enemy.x, enemy.y) <= me.weapons["front"]["reach"]:
            cmds.append(grab("front"))
    else:
        # Release after holding for 5 seconds
        start = me.memory.get("hold_start")
        if start is None:
            me.memory["hold_start"] = arena.time
        elif arena.time - start >= 5.0:
            cmds.append(release("front"))
            me.memory.pop("hold_start", None)

    return cmds

